<script lang="ts">
    import ContextTip from "../components/ContextTip.svelte";
  import StringOrSnippet from "../util/StringOrSnippet.svelte";
    import type { Snippet } from "svelte";

    /**
     * @description
     * The label component is used to create a label for an input element.
     * @example
     * <Label label="Name" />
     * {#snippet l()}
     * <Label label={l} />
     * {/snippet}
     */
    let {
        id,
        label,
        help,
        tip,
        required,
    }: {
        /** The id of the input element */
        id?: string;
        /** The label for the input */
        label?: string | Snippet;
        /** The help text for the input */
        tip?: string | Snippet;
        /** The help text for the input */
        help?: string | Snippet;
        /** Whether the input is required */
        required?: boolean;
    } = $props();

</script>

{#if label}
    <label for={id}>
        {#if typeof label === 'string'}
            <span>
                {label} {#if required}<span aria-hidden="true">*</span>{/if}
            </span>
        {:else}
            <span>
                {@render label()}
            </span>
        {/if}
        {#if help}
            <span class="Help">
                <StringOrSnippet content={help} />
            </span>
        {/if}
        {#if tip}
            <ContextTip {tip} />
        {/if}
    </label>
{/if}

<style>
    label {
        cursor: var(--cursor, default);
        text-wrap: balance;
        display: inline-grid;
        grid-template-columns: 1fr;
        gap: var(--form-label-gap, var(--space-md));
        align-items: center;
    }
    label:has(.Help),
    label:has(:global(.ContextTip)) {
        grid-template-columns: 1fr auto;
    }
    label:has(.Help):has(:global(.ContextTip)) {
        grid-template-columns: 1fr auto auto;
    }
    label > span > span {
        font-weight: var(--font-weight-medium);
        color: var(--field-color-danger);
        padding-inline: 0.175em;
    }
    .Help {
        font-weight: var(--font-weight-normal);
    }
    .Help :global(a) {
        color: var(--link-color);
    }
    .Help :global(a:hover) {
        color: var(--link-color-hover);
    }
</style>